/// <reference types="vite/client" />
interface PendingEmail { id:string; to:string; subject:string; body:string; createdAt:number }
interface Window { jarvis: { controlWindow(action: 'minimize'|'maximize'|'close'): Promise<void>; getSystemInfo(): Promise<{cpu:number;memory:number;platform:string}>; loadSchoolProfile():Promise<string>; saveSchoolProfile(profile:string):Promise<boolean>; loadHistory(): Promise<ConversationStore>; saveHistory(store:ConversationStore):Promise<void>; checkConnection():Promise<ConnectionStatus>; hasApiKey():Promise<boolean>; hasFishAudioKey():Promise<boolean>; getCredentialStatus():Promise<{groq:boolean;fish:boolean;openai:boolean}>; saveCredential(name:'groq'|'fish-audio'|'openai',key:string):Promise<boolean>; speakText(text:string):Promise<{audioBase64:string;mimeType:string}>; transcribeAudio(audioBase64:string,mimeType:string):Promise<string>; openGmailDraft(draft:{to:string;subject:string;body:string}):Promise<boolean>; gmailStatus():Promise<{connected:boolean;calendarReady:boolean;contactsReady:boolean;clientId:string}>;smsConfig():Promise<{accountSid:string;from:string;to:string;authTokenSet:boolean;configured:boolean}>; saveSmsConfig(config:{accountSid:string;authToken:string;from:string;to:string}):Promise<{configured:boolean}>; connectGmail(clientId:string,clientSecret:string):Promise<boolean>; disconnectGmail():Promise<boolean>; confirmEmail(id:string):Promise<{sent:boolean;to:string;messageId?:string}>; cancelEmail(id:string):Promise<boolean>; onPendingEmail(callback:(email:PendingEmail|null)=>void):()=>void; openPrintableInSlicer():Promise<{opened:boolean;filePath?:string}>; createModelSource(prompt:string):Promise<{path:string;code:string}>; createBlenderModel(description:string):Promise<{title:string;blendPath:string;scriptPath:string}>; openBlendFile():Promise<{opened:boolean;filePath?:string}>; showModelFile(path:string):Promise<boolean>; sendMessage(messages:{role:'user'|'assistant';content:string}[],model?:string):Promise<boolean>; onToken(callback:(token:string)=>void):()=>void; onDone(callback:()=>void):()=>void } }
interface ChatMessage { id: string; role: 'user'|'assistant'; content: string; time: number }
